owned_rules:
table ip dns_policy_poc {
	set pods {
		type ifname . ipv4_addr
		elements = { "eni3b790ef6f68" . 10.244.0.6 }
	}

	chain pre {
		type nat hook prerouting priority dstnat - 10; policy accept;
		iifname . ip saddr @pods meta l4proto { tcp, udp } th dport 53 dnat to 169.254.29.53:50052
	}
}
